export type ResultMessage = ({
    type: 'result';
    subtype: 'success';
    uuid: string;
    session_id: string;
    duration_ms: number;
    duration_api_ms: number;
    is_error: boolean;
    num_turns: number;
    result: string;
    total_cost_usd: number;
    usage: NonNullableUsage;
    permission_denials: PermissionDenial[];
} | {
    type: 'result';
    subtype: 'error_max_turns';
    uuid: string;
    session_id: string;
    duration_ms: number;
    duration_api_ms: number;
    is_error: boolean;
    num_turns: number;
    total_cost_usd: number;
    usage: NonNullableUsage;
    permission_denials: PermissionDenial[];
} | {
    type: 'result';
    subtype: 'error_during_execution';
    uuid: string;
    session_id: string;
    duration_ms: number;
    duration_api_ms: number;
    is_error: boolean;
    num_turns: number;
    total_cost_usd: number;
    usage: NonNullableUsage;
    permission_denials: PermissionDenial[];
    errors: string[];
    /**
     * 结构化错误信息（向前兼容追加，与 `errors: string[]` **并列且索引对齐**）。
     *
     * 关键契约：
     * - **长度等于** `errors.length`：`errors_info[i]` 描述 `errors[i]`，一一对应；
     * - 单条抽不出任何维度时该位置为 `null`（不用 `{}` 以免与"抽到空对象"混淆）；
     * - **全部为 `null`** 时整体省略 `errors_info` 字段，避免污染 fixture / snapshot；
     * - 字段全部可选：`status` (HTTP 状态码)、`code` (SDK/业务码)、`category`
     *   (与 acp-agent.ts `classifyErrorAsRequestError` 分类对齐)、`details` (脱敏文案)。
     *
     * 例外（`is_error: true` 的终态）：抛出物本身没有文案时（裸 `throw`、空 message 的
     * `Error`、无 message 的对象），该槽位不再是 `null`，而是带
     * `code: 'cbc_empty_error'` + 兜底 `details`。否则 `errors[i]` 与 `errors_info[i]`
     * 同时为空，下游 `BuildErrorMessageFromCLIErrors` 会整条丢掉错误 `_meta`，
     * 终态在观测侧退化为不可归因的 `stop_reason=refusal` + `error=""`。
     *
     * 详见 `result-message-utils.ts` 的 `buildErrorTerminalFields` /
     * `buildErrorsInfo` / `extractStructuredErrorInfo`。
     */
    errors_info?: Array<{
        status?: number;
        code?: string | number;
        category?: string;
        details?: string;
    } | null>;
}) & ResultUsageExtension & ResultTerminalExtension;
type ApiKeySource = string;
